<?php
namespace App\Http\Controllers;
use App\Services\OfficeRegistrationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class OfficeController extends Controller{
public function __construct(private OfficeRegistrationService $registration){}
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('document_clerk')||$r->user()->canDo('office.view')||$r->user()->canDo('office.manage'),403);}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('document_clerk')||$r->user()->canDo('office.manage'),403);}
public function index(Request $r){$this->view($r);$today=date('Y-m-d');$stats=['today'=>DB::table('office_registrations')->where('registration_date',$today)->count(),'unregistered'=>DB::table('official_documents')->where('status','draft')->count(),'routing'=>DB::table('official_documents')->whereIn('status',['registered','routing','approved'])->count(),'overdue'=>DB::table('document_tasks')->whereNotIn('status',['done','cancelled'])->where('due_on','<',$today)->count(),'dispatch'=>DB::table('office_dispatches')->where('status','prepared')->count(),'archive'=>DB::table('official_documents')->where('status','archived')->count()];$recent=DB::table('office_registrations as r')->join('official_documents as d','d.id','=','r.official_document_id')->leftJoin('office_correspondents as c','c.id','=','r.office_correspondent_id')->select('r.*','d.title','d.direction','d.status','c.name as correspondent_name')->orderByDesc('r.id')->limit(30)->get();return view('office.index',compact('stats','recent'));}
public function journal(Request $r,$direction){$this->view($r);abort_unless(in_array($direction,['incoming','outgoing','internal']),404);$q=DB::table('official_documents as d')->leftJoin('office_registrations as r','r.official_document_id','=','d.id')->leftJoin('office_correspondents as c','c.id','=','r.office_correspondent_id')->where('d.direction',$direction)->select('d.*','r.registration_number','r.registration_date','r.delivery_method','c.name as correspondent_name')->orderByDesc('r.registration_date')->orderByDesc('d.id');if($r->filled('q'))$q->where(function($x)use($r){$x->where('d.title','like','%'.$r->q.'%')->orWhere('r.registration_number','like','%'.$r->q.'%')->orWhere('d.external_number','like','%'.$r->q.'%');});return view('office.journal',['rows'=>$q->limit(500)->get(),'direction'=>$direction]);}
public function registration(Request $r){$this->manage($r);$docs=DB::table('official_documents')->where('status','draft')->orderByDesc('id')->get();$correspondents=DB::table('office_correspondents')->where('active',1)->orderBy('name')->get();return view('office.registration',compact('docs','correspondents'));}
public function register(Request $r,$document){$this->manage($r);$x=$r->validate(['office_correspondent_id'=>'nullable|exists:office_correspondents,id','delivery_method'=>'nullable|in:hand,email,post,courier,system']);$num=$this->registration->register($document,$r->user()->id,$x['office_correspondent_id']??null,$x['delivery_method']??null);return redirect()->route('edo.show',$document)->with('success','Документ зарегистрирован: '.$num);}
public function correspondent(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:500','type'=>'required|in:organization,person,authority','inn'=>'nullable|string|max:20','address'=>'nullable|string|max:1000','contact'=>'nullable|string|max:255','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255']);DB::table('office_correspondents')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function control(Request $r){$this->view($r);$rows=DB::table('document_tasks as t')->join('official_documents as d','d.id','=','t.official_document_id')->join('users as u','u.id','=','t.assigned_to')->select('t.*','d.number','d.title','u.name as assignee_name')->whereNotIn('t.status',['cancelled'])->orderByRaw("CASE WHEN t.status!='done' AND t.due_on < date('now') THEN 0 ELSE 1 END")->orderBy('t.due_on')->get();return view('office.control',compact('rows'));}
}